//! A read-only look inside `word/vbaProject.bin` (`vba.rs`): which modules it holds and what
//! source they carry. Nothing here runs anything. Fixtures are generated by our own code (a
//! test-only compressor), no files produced by Word.

use std::io::{Cursor, Write};

const CODE_PAGE_1252: u16 = 0x04E4;

/// The test-only MS-OVBA compressor: all-literal chunks (flag bytes 0x00, no copy tokens),
/// which is a valid compressed container any decompressor reads. Test code only.
fn compress(source: &[u8]) -> Vec<u8> {
    let mut out = vec![0x01];
    for literals in source.chunks(3600) {
        // A flag byte names every eight literals; the data is flags + literals, and the stored
        // size is the data length - 1. All-literal data is 9/8 the literals, so 3600 literals
        // (4050 bytes) stay inside the 12-bit size.
        let data_len = literals.len().div_ceil(8) + literals.len();
        let header = 0xB000u16 | (data_len - 1) as u16;
        out.extend(header.to_le_bytes());
        for group in literals.chunks(8) {
            out.push(0x00); // flag byte: eight literals
            out.extend_from_slice(group);
        }
    }
    out
}

/// A dir stream: flat `id + size + payload` records ([MS-OVBA] §2.3.4.2).
fn record(out: &mut Vec<u8>, id: u16, payload: &[u8]) {
    out.extend(id.to_le_bytes());
    out.extend((payload.len() as u32).to_le_bytes());
    out.extend_from_slice(payload);
}

/// PROJECTVERSION ([MS-OVBA] §2.3.4.2.1.11): id, reserved size 4, then 4 + 2 bytes of
/// version — not a `record()`.
fn project_version(out: &mut Vec<u8>) {
    out.extend(0x0009u16.to_le_bytes());
    out.extend(0x00000004u32.to_le_bytes()); // Reserved
    out.extend(0x00000002u32.to_le_bytes()); // VersionMajor
    out.extend(0x0001u16.to_le_bytes()); // VersionMinor
}

/// The dir stream for one procedural module: its names, offset, and type.
fn dir_module() -> Vec<u8> {
    dir_for(&[("Module1", "Module1")])
}

/// A dir stream for modules: each entry is (module name, stream name) — stream names may
/// repeat, as a hostile project's do.
fn dir_for(modules: &[(&str, &str)]) -> Vec<u8> {
    let mut dir = Vec::new();
    record(&mut dir, 0x0001, &0x00000001u32.to_le_bytes()); // SysKind: Windows
    record(&mut dir, 0x0003, &CODE_PAGE_1252.to_le_bytes()); // CodePage
    project_version(&mut dir); // PROJECTVERSION, before PROJECTMODULES as real projects have
    // PROJECTMODULES: Count is a u16 ([MS-OVBA] §2.3.4.2.2.1).
    record(&mut dir, 0x000F, &(modules.len() as u16).to_le_bytes());
    record(&mut dir, 0x0013, &0xFFFFu16.to_le_bytes()); // ProjectCookie
    for (name, stream) in modules {
        record(&mut dir, 0x0019, name.as_bytes()); // MODULENAME
        record(&mut dir, 0x0047, &utf16(name)); // MODULENAMEUNICODE
        record(&mut dir, 0x001A, stream.as_bytes()); // MODULESTREAMNAME
        record(&mut dir, 0x0032, &utf16(stream)); // MODULESTREAMNAMEUNICODE
        record(&mut dir, 0x0031, &4u32.to_le_bytes()); // MODULEOFFSET: 4 cache bytes first
        record(&mut dir, 0x002C, &0u32.to_le_bytes()); // MODULECOOKIE
        record(&mut dir, 0x0021, &0u32.to_le_bytes()); // MODULETYPE: procedural
        record(&mut dir, 0x002B, &0u32.to_le_bytes()); // terminator
    }
    dir
}

/// UTF-16LE bytes, as the Unicode name records carry them.
fn utf16(s: &str) -> Vec<u8> {
    let mut out = Vec::new();
    for unit in s.encode_utf16() {
        out.extend(unit.to_le_bytes());
    }
    out
}

/// A compound file with `/VBA/dir` and the named module streams.
fn cfb_project_streams(dir: &[u8], streams: &[(&str, &[u8])]) -> Vec<u8> {
    let mut comp = cfb::CompoundFile::create(Cursor::new(Vec::new())).unwrap();
    comp.create_storage("/VBA").unwrap();
    comp.create_stream("/VBA/dir").unwrap().write_all(dir).unwrap();
    for (name, bytes) in streams {
        comp.create_stream(format!("/VBA/{name}")).unwrap().write_all(bytes).unwrap();
    }
    comp.flush().unwrap();
    comp.into_inner().into_inner()
}

/// A compound file with `/VBA/dir` and one module stream: a 4-byte cache, then the source.
fn cfb_project(dir: &[u8], module: &[u8]) -> Vec<u8> {
    cfb_project_streams(dir, &[("Module1", module)])
}

fn module_stream(source: &[u8]) -> Vec<u8> {
    let mut bytes = vec![0xDE, 0xAD, 0xBE, 0xEF]; // performance cache
    bytes.extend(compress(source));
    bytes
}

#[test]
fn a_roundtrip_through_all_literal_chunks() {
    for source in [b"".as_slice(), b"Sub Hello()\n    MsgBox \"Hi\"\nEnd Sub\n", "комментарий с кириллицей".as_bytes()] {
        let round = wordcraft_docx::vba::decompress(&compress(source), 1 << 20).unwrap();
        assert_eq!(round, source);
    }
}

#[test]
fn a_multi_chunk_source_comes_through() {
    let source: Vec<u8> = (0..10_000u32).map(|i| b'a' + (i % 26) as u8).collect();
    let round = wordcraft_docx::vba::decompress(&compress(&source), 1 << 20).unwrap();
    assert_eq!(round, source);
}

#[test]
fn a_raw_chunk_comes_through_as_literals() {
    // An uncompressed chunk: a header without the signature, then 4096 literal bytes.
    let source: Vec<u8> = (0..8192u32).map(|i| b'a' + (i % 26) as u8).collect();
    let mut container = vec![0x01];
    let (raw, rest) = source.split_at(4096);
    container.extend(0x0000u16.to_le_bytes());
    container.extend_from_slice(raw);
    container.extend(compress(rest)[1..].to_vec());
    let round = wordcraft_docx::vba::decompress(&container, 1 << 20).unwrap();
    assert_eq!(round, source);
}

#[test]
fn a_copy_token_copies_what_came_before() {
    // Three literals, then one copy token: flags 0b0000_1000 — bits 0..2 clear (literals),
    // bit 3 set (copy). Per [MS-OVBA] §2.4.1.3.19.4 at difference 3 (≤ 16): 4 offset bits
    // (the token's high bits) and 12 length bits (the low bits) — copying the three bytes
    // before it.
    let mut chunk = vec![0x08, b'a', b'b', b'c'];
    // difference 3: offset 3 → stored 2 (offset − 1, in the high 4 bits);
    // length 3 → stored 0 (length − 3, in the low 12 bits).
    let token = 2u16 << 12;
    chunk.extend(token.to_le_bytes());
    let mut container = vec![0x01];
    // The chunk is the data: the stored size is the data length - 1.
    let header = 0xB000u16 | (chunk.len() as u16 - 1);
    container.extend(header.to_le_bytes());
    container.extend(chunk);
    let round = wordcraft_docx::vba::decompress(&container, 1 << 20).unwrap();
    assert_eq!(round, b"abcabc".as_slice());
}

#[test]
fn a_copy_token_at_the_16_byte_boundary_uses_four_offset_bits() {
    // [MS-OVBA] §2.4.1.3.19.4: at difference == 16 the offset still takes 4 bits
    // (ceil(log2(16)) = 4); a 5-bit table would decode real tokens wrong.
    let literals: Vec<u8> = (0..16u32).map(|i| b'a' + (i % 26) as u8).collect();
    let mut chunk = Vec::new();
    for group in literals.chunks(8) {
        chunk.push(0x00); // flag byte: eight literals
        chunk.extend_from_slice(group);
    }
    // At difference 16: offset 16 → stored 15 (the token's high 4 bits),
    // length 3 → stored 0 (the low 12 bits).
    chunk.push(0x01); // flag byte: one copy token
    chunk.extend(0xF000u16.to_le_bytes());
    let mut container = vec![0x01];
    let header = 0xB000u16 | (chunk.len() as u16 - 1);
    container.extend(header.to_le_bytes());
    container.extend(chunk);
    let round = wordcraft_docx::vba::decompress(&container, 1 << 20).unwrap();
    let mut expected = literals.clone();
    expected.extend_from_slice(&literals[0..3]);
    assert_eq!(round, expected);
}

#[test]
fn a_project_lists_its_modules_and_their_source() {
    let source = b"Sub Hello()\n    MsgBox \"Hi\"\nEnd Sub\n".as_slice();
    let project = wordcraft_docx::vba::project(&cfb_project(&compress(&dir_module()), &module_stream(source))).unwrap();
    assert_eq!(project.code_page, CODE_PAGE_1252);
    assert!(!project.truncated);
    assert_eq!(project.modules.len(), 1);
    let module = &project.modules[0];
    assert_eq!(module.name, "Module1");
    assert_eq!(module.stream_name, "Module1");
    assert_eq!(module.text_offset, 4);
    assert!(module.procedural);
    assert!(!module.truncated);
    assert_eq!(module.source.as_deref(), Some(String::from_utf8_lossy(source).as_ref()));
}

#[test]
fn a_raw_source_below_the_offset_signature_is_taken_as_is() {
    // A module whose source doesn't start with the container signature: raw source.
    let raw = b"Option Explicit\n";
    let mut module = vec![0u8; 4]; // cache
    module.extend_from_slice(raw);
    let project = wordcraft_docx::vba::project(&cfb_project(&compress(&dir_module()), &module)).unwrap();
    assert_eq!(project.modules[0].source.as_deref(), Some("Option Explicit\n"));
}

#[test]
fn a_module_whose_stream_is_missing_is_listed_without_source() {
    // A stream name no stream has: the module is listed without source.
    let mut dir = Vec::new();
    record(&mut dir, 0x0001, &0x00000001u32.to_le_bytes());
    record(&mut dir, 0x0003, &CODE_PAGE_1252.to_le_bytes());
    record(&mut dir, 0x000F, &1u16.to_le_bytes());
    record(&mut dir, 0x0019, b"Nowhere");
    record(&mut dir, 0x001A, b"Nowhere");
    record(&mut dir, 0x0031, &0u32.to_le_bytes());
    record(&mut dir, 0x0021, &0u32.to_le_bytes());
    record(&mut dir, 0x002B, &0u32.to_le_bytes());
    let project = wordcraft_docx::vba::project(&cfb_project(&compress(&dir), &module_stream(b""))).unwrap();
    assert_eq!(project.modules.len(), 1);
    assert_eq!(project.modules[0].name, "Nowhere");
    assert_eq!(project.modules[0].source, None);
}

#[test]
fn a_stream_name_that_cannot_name_a_stream_is_skipped() {
    // A stream name with a slash can't name a module stream; the module is listed without
    // source rather than reading some other path.
    let mut dir = Vec::new();
    record(&mut dir, 0x0003, &CODE_PAGE_1252.to_le_bytes());
    record(&mut dir, 0x000F, &1u16.to_le_bytes());
    record(&mut dir, 0x0019, b"../escape");
    record(&mut dir, 0x001A, b"../escape");
    record(&mut dir, 0x0031, &0u32.to_le_bytes());
    record(&mut dir, 0x002B, &0u32.to_le_bytes());
    let project = wordcraft_docx::vba::project(&cfb_project(&compress(&dir), &module_stream(b"sub"))).unwrap();
    assert_eq!(project.modules.len(), 1);
    assert_eq!(project.modules[0].source, None);
}

#[test]
fn hostile_containers_error_without_panicking() {
    let source = b"Sub Hello()\nEnd Sub\n".as_slice();
    let good = compress(source);
    // No signature byte, wrong signature, garbage.
    assert!(wordcraft_docx::vba::decompress(&[], 1 << 20).is_err());
    assert!(wordcraft_docx::vba::decompress(&[0x00], 1 << 20).is_err());
    assert!(wordcraft_docx::vba::decompress(&[0x02, 0x01, 0x02], 1 << 20).is_err());
    assert!(wordcraft_docx::vba::decompress(&[0x01, 0xFF, 0xFF], 1 << 20).is_err());
    // Truncations: the header, then the chunk, cut at every byte.
    for n in 1..good.len() {
        let cut = good[..n].to_vec();
        let round = wordcraft_docx::vba::decompress(&cut, 1 << 20);
        if let Ok(round) = round {
            assert!(round.len() <= source.len(), "a cut container decompressed past {n}");
        }
    }
    // A cap: decompressing past it says Limit, not a panic.
    let big: Vec<u8> = std::iter::repeat_n(b'x', 10_000).collect();
    assert!(matches!(wordcraft_docx::vba::decompress(&compress(&big), 1_000), Err(wordcraft_docx::DocxError::Limit(_))));
    // A copy token that reaches past the chunk start is refused.
    let chunk = vec![0x00, b'a', b'b']; // flags 0x00: literals only, fine.
    let mut container = vec![0x01];
    container.extend((0xB000u16 | (chunk.len() as u16 - 1)).to_le_bytes());
    container.extend(chunk);
    assert_eq!(wordcraft_docx::vba::decompress(&container, 1 << 20).unwrap(), b"ab");
}

#[test]
fn a_hostile_project_errors_or_reads_without_panicking() {
    let source = b"Sub Hello()\nEnd Sub\n".as_slice();
    let good_dir = compress(&dir_module());
    let good_module = module_stream(source);
    // Not a compound file at all.
    assert!(wordcraft_docx::vba::project(&[]).is_err());
    assert!(wordcraft_docx::vba::project(&[0xD0, 0xCF, 0x11, 0xE0]).is_err());
    assert!(wordcraft_docx::vba::project(b"not a compound file, just text").is_err());
    // A good compound file with damaged streams.
    let comp = cfb_project(&good_dir, &good_module);
    for n in (0..comp.len()).step_by(997) {
        let cut = comp[..n].to_vec();
        // A cut compound file either reads or errors; it must not panic.
        let _ = wordcraft_docx::vba::project(&cut);
    }
    // A dir stream that isn't a compressed container at all.
    let project = wordcraft_docx::vba::project(&cfb_project(&[0xFF, 0xFF], &good_module));
    assert!(project.is_err());
}

#[test]
fn a_dir_stream_cut_at_every_record_still_walks() {
    let dir = compress(&dir_module());
    for n in 1..dir.len() {
        let cut = dir[..n].to_vec();
        // The walker is lenient: a cut dir stream reads what it can or errors.
        let project = wordcraft_docx::vba::project(&cfb_project(&cut, &module_stream(b"")));
        if let Ok(project) = project {
            assert!(project.modules.len() <= 1, "a cut dir listed more modules at {n}");
        }
    }
}

#[test]
fn a_project_version_record_cut_inside_its_twelve_bytes_ends_the_walk() {
    // The record is 12 bytes (id, reserved 4, version 4 + 2). Cut inside them, the walker
    // stops at the cut instead of stepping past the stream; the module named after it is
    // never reached.
    let mut record_bytes = Vec::new();
    project_version(&mut record_bytes);
    let mut dir = Vec::new();
    record(&mut dir, 0x0001, &0x00000001u32.to_le_bytes()); // SysKind
    record(&mut dir, 0x0003, &CODE_PAGE_1252.to_le_bytes()); // CodePage
    dir.extend_from_slice(&record_bytes[..7]); // past the 6-byte header, inside the version
    record(&mut dir, 0x0019, b"Module1"); // MODULENAME, after the cut
    let project = wordcraft_docx::vba::project(&cfb_project(&compress(&dir), &module_stream(b""))).unwrap();
    assert!(project.modules.is_empty());
}

#[test]
fn more_than_the_module_cap_is_truncated() {
    let mut dir = Vec::new();
    record(&mut dir, 0x0003, &CODE_PAGE_1252.to_le_bytes());
    record(&mut dir, 0x000F, &1000u16.to_le_bytes()); // the project claims 1000 modules
    for i in 0..300u32 {
        let name = format!("Module{i}");
        record(&mut dir, 0x0019, name.as_bytes());
        record(&mut dir, 0x001A, name.as_bytes());
        record(&mut dir, 0x0031, &0u32.to_le_bytes());
        record(&mut dir, 0x002B, &0u32.to_le_bytes());
    }
    let project = wordcraft_docx::vba::project(&cfb_project(&compress(&dir), &module_stream(b""))).unwrap();
    assert_eq!(project.modules.len(), wordcraft_docx::vba::MAX_MODULES);
    assert!(project.truncated);
    // A module beyond the cap is skipped whole: the last kept one keeps its own records.
    assert_eq!(project.modules[255].stream_name, "Module255");
    assert_eq!(project.modules[255].name, "Module255");
}

#[test]
fn a_source_past_the_cap_is_cut_and_says_so() {
    // #5483 review: past the cap decompress used to fail, so a module with about a mebibyte
    // of comments said source: None, sourceLen: 0 and truncated: false — its code was hidden
    // from the audit. The output stops at the cap with an overflow instead.
    let mut source = b"Sub Hidden()\nEnd Sub\n".to_vec();
    source.extend(std::iter::repeat_n(b'x', wordcraft_docx::vba::MAX_SOURCE as usize));
    let project = wordcraft_docx::vba::project(&cfb_project(&compress(&dir_module()), &module_stream(&source))).unwrap();
    let module = &project.modules[0];
    assert!(module.truncated, "the source past the cap is told of, not hidden");
    let src = module.source.as_deref().unwrap_or_default();
    assert_eq!(src.len() as u64, wordcraft_docx::vba::MAX_SOURCE);
    assert!(src.starts_with("Sub Hidden()"), "the code before the padding still shows");
}

#[test]
fn a_project_of_many_modules_naming_one_stream_is_bounded() {
    // #5483 review: 256 modules all naming one small stream that decompresses to the cap,
    // full of bytes 0x80-0xFF that lossy decoding turns into 3 chars each, used to hold about
    // 768 MiB. Each distinct stream is read once and the source all modules carry counts
    // against one budget ([`vba::MAX_TOTAL_SOURCE`]).
    let names: Vec<String> = (0..wordcraft_docx::vba::MAX_MODULES).map(|i| format!("Module{i}")).collect();
    let pairs: Vec<(&str, &str)> = names.iter().map(|n| (n.as_str(), "Big")).collect();
    let dir = compress(&dir_for(&pairs));
    // 0xFF bytes: lossy decoding turns each into one replacement character, 3 chars — the
    // reviewer's 0x80-0xFF stream at its most expansive. Past the cap, like the review's
    // comments, so the first copy is cut too.
    let big: Vec<u8> = vec![0xFF; wordcraft_docx::vba::MAX_SOURCE as usize + 500];
    let project = wordcraft_docx::vba::project(&cfb_project_streams(&dir, &[("Big", &module_stream(&big))])).unwrap();
    assert_eq!(project.modules.len(), wordcraft_docx::vba::MAX_MODULES);
    let total: u64 = project.modules.iter().filter_map(|m| m.source.as_ref().map(|s| s.len() as u64)).sum();
    assert!(total <= wordcraft_docx::vba::MAX_TOTAL_SOURCE, "the source all modules carry is bounded, got {total}");
    // The budget spends across the copies: the first modules carry what is left of it, the
    // rest are listed without source.
    assert_eq!(project.modules.iter().filter(|m| m.source.is_none()).count(), wordcraft_docx::vba::MAX_MODULES - 2);
    assert!(project.modules[0].truncated && project.modules[1].truncated, "a cut copy says so");
}

#[test]
fn a_cp1252_stream_name_opens_through_its_unicode_record() {
    // #5483 review: MODULESTREAMNAME is MBCS in the project's code page; decoded as lossy
    // UTF-8, a cp1252 name such as Módulo1 (0xF3 is ó there, invalid UTF-8 alone) can't open
    // its stream. MODULESTREAMNAMEUNICODE (0x0032) names it as the compound file stores it.
    let mut dir = Vec::new();
    record(&mut dir, 0x0003, &CODE_PAGE_1252.to_le_bytes());
    record(&mut dir, 0x000F, &1u16.to_le_bytes());
    record(&mut dir, 0x0019, b"M\xf3dulo1"); // MODULENAME, cp1252
    record(&mut dir, 0x001A, b"M\xf3dulo1"); // MODULESTREAMNAME, cp1252
    record(&mut dir, 0x0032, &utf16("M\u{00f3}dulo1")); // MODULESTREAMNAMEUNICODE
    record(&mut dir, 0x0031, &4u32.to_le_bytes());
    record(&mut dir, 0x0021, &0u32.to_le_bytes());
    record(&mut dir, 0x002B, &0u32.to_le_bytes());
    let project =
        wordcraft_docx::vba::project(&cfb_project_streams(&compress(&dir), &[("M\u{00f3}dulo1", &module_stream(b"Sub Hi()\nEnd Sub\n"))])).unwrap();
    assert_eq!(project.modules[0].stream_name, "M\u{00f3}dulo1");
    assert_eq!(project.modules[0].source.as_deref(), Some("Sub Hi()\nEnd Sub\n"));
}

#[test]
fn a_project_of_more_streams_than_the_cache_holds_still_reports_every_module() {
    // The stream cache is bounded by [`MAX_CACHED_STREAMS`]: streams past it are read again
    // instead of being retained, so a project of distinct streams sharing one chain can't
    // make the cache hold every stream's bytes. Every module still reports its source — the
    // last one re-reads a stream the cache didn't keep.
    // Five streams of ~1.7 MiB each: four fit the cache's bound, the fifth is read again.
    // Each one is under the stream read's cap, and the sources all fit the source budget.
    let filler = vec![b'Z'; 1_700_000];
    let source = |i: usize| format!("Sub M{i}()\nEnd Sub\n");
    let names = ["M1", "M2", "M3", "M4", "M5"];
    let streams: Vec<(&str, Vec<u8>)> = names
        .iter()
        .enumerate()
        .map(|(i, name)| {
            let mut bytes = filler.clone();
            bytes.extend(module_stream(source(i + 1).as_bytes()));
            (*name, bytes)
        })
        .collect();
    // A dir stream with MODULEOFFSET naming each stream's cache: the filler comes first.
    let offset = (filler.len() + 4) as u32;
    let modules: [(&str, &str); 6] = [("M1", "M1"), ("M2", "M2"), ("M3", "M3"), ("M4", "M4"), ("M5", "M5"), ("Again", "M5")];
    let mut dir = Vec::new();
    record(&mut dir, 0x0001, &0x00000001u32.to_le_bytes());
    record(&mut dir, 0x0003, &CODE_PAGE_1252.to_le_bytes());
    project_version(&mut dir);
    record(&mut dir, 0x000F, &(modules.len() as u16).to_le_bytes());
    record(&mut dir, 0x0013, &0xFFFFu16.to_le_bytes());
    for (name, stream) in modules {
        record(&mut dir, 0x0019, name.as_bytes());
        record(&mut dir, 0x0047, &utf16(name));
        record(&mut dir, 0x001A, stream.as_bytes());
        record(&mut dir, 0x0032, &utf16(stream));
        record(&mut dir, 0x0031, &offset.to_le_bytes());
        record(&mut dir, 0x002C, &0u32.to_le_bytes());
        record(&mut dir, 0x0021, &0u32.to_le_bytes());
        record(&mut dir, 0x002B, &0u32.to_le_bytes());
    }
    let refs: Vec<(&str, &[u8])> = streams.iter().map(|(n, b)| (*n, b.as_slice())).collect();
    let project = wordcraft_docx::vba::project(&cfb_project_streams(&compress(&dir), &refs)).unwrap();
    assert_eq!(project.modules.len(), 6);
    for (i, module) in project.modules.iter().enumerate() {
        let want = if i == 5 { source(5) } else { source(i + 1) };
        assert_eq!(module.source.as_deref(), Some(want.as_str()), "{} didn't report its source", module.name);
    }
    // The streams sum past the cache's bound, and each one read is under the stream cap.
    let total: u64 = streams.iter().map(|(_, b)| b.len() as u64).sum();
    assert!(total > wordcraft_docx::vba::MAX_CACHED_STREAMS, "the fixture should outgrow the cache: {total}");
    assert!(streams[0].1.len() as u64 <= wordcraft_docx::vba::MAX_MODULE_STREAM, "a fixture stream is over the read cap");
}
